package jp.nw.controller;
import java.io.*;import java.nio.file.*;import java.sql.*;import java.util.*;import javax.servlet.*;import javax.servlet.annotation.*;import javax.servlet.http.*;import jp.nw.entity.UserEntity;import jp.nw.parts.DBBase;
@WebServlet("/Attachment") @MultipartConfig(maxFileSize=10_485_760,maxRequestSize=11_534_336)
public class AttachmentController extends HttpServlet{
 private Path root(){String v=System.getenv("ATTACHMENT_DIR");return Paths.get(v==null||v.isBlank()?System.getProperty("java.io.tmpdir")+"/nwproject-attachments":v);}
 protected void doPost(HttpServletRequest req,HttpServletResponse res)throws IOException,ServletException{UserEntity u=(UserEntity)req.getSession().getAttribute("loginUser");String type=req.getParameter("ownerType"),owner=req.getParameter("ownerId");if(!Set.of("REPORT","CHAT","SCHEDULE","APPROVAL").contains(type)||owner==null||owner.isBlank()){res.sendError(400);return;}Part part=req.getPart("file");String original=Paths.get(part.getSubmittedFileName()).getFileName().toString();if(original.isBlank()||part.getSize()==0){res.sendError(400,"ファイルを選択してください。");return;}Files.createDirectories(root());String stored=UUID.randomUUID().toString();Path target=root().resolve(stored).normalize();if(!target.startsWith(root())){res.sendError(400);return;}try(InputStream in=part.getInputStream()){Files.copy(in,target);}DBBase db=new DBBase();try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("INSERT INTO attachment(owner_type,owner_id,uploaded_by_id,original_name,stored_name,content_type,file_size) VALUES(?,?,?,?,?,?,?)")){p.setString(1,type);p.setString(2,owner);p.setString(3,u.getUserId());p.setString(4,original);p.setString(5,stored);p.setString(6,Optional.ofNullable(part.getContentType()).orElse("application/octet-stream"));p.setLong(7,part.getSize());p.executeUpdate();}catch(SQLException e){Files.deleteIfExists(target);throw new ServletException(e);}res.sendRedirect(Optional.ofNullable(req.getHeader("Referer")).orElse(req.getContextPath()+"/Portal"));}
 protected void doGet(HttpServletRequest req,HttpServletResponse res)throws IOException{long id=Long.parseLong(req.getParameter("id"));DBBase db=new DBBase();try(Connection c=db.getConnection();PreparedStatement p=c.prepareStatement("SELECT original_name,stored_name,content_type,file_size FROM attachment WHERE attachment_id=?")){p.setLong(1,id);try(ResultSet r=p.executeQuery()){if(!r.next()){res.sendError(404);return;}Path file=root().resolve(r.getString(2)).normalize();if(!file.startsWith(root())||!Files.exists(file)){res.sendError(404);return;}res.setContentType(r.getString(3));res.setContentLengthLong(r.getLong(4));res.setHeader("Content-Disposition","attachment; filename*=UTF-8''"+java.net.URLEncoder.encode(r.getString(1),java.nio.charset.StandardCharsets.UTF_8).replace("+","%20"));Files.copy(file,res.getOutputStream());}}catch(SQLException e){throw new IOException(e);}}
}
